<body>

  <div class="classroom-container">

    <!-- 左侧：SVG 交互式城市公共设施地图 -->
    <div class="map-area">
      <svg viewBox="0 0 550 600" width="100%" height="100%" xmlns="http://www.w3.org/2000/svg">
        <!-- 装饰性背景：天空与地面 -->
