          <text x="0" y="25" font-size="12" fill="#2d3748" font-weight="bold" text-anchor="middle" bgcolor="#ffffff">居民家庭</text>
        </g>

        <!-- 纳税源头节点 2：企业公司 -->
        <g transform="translate(450, 460)">
          <circle cx="0" cy="0" r="35" fill="#4c51bf" opacity="0.15" />
          <circle cx="0" cy="0" r="28" fill="#4c51bf" />
          <!-- 工厂/写字楼简易图标 -->
          <rect x="-12" y="-12" width="10" height="24" fill="#ffffff" />
          <rect x="2" y="-4" width="10" height="16" fill="#ffffff" />
