            <div class="dot" id="dot-hospital"></div>
            <div class="dot" id="dot-road"></div>
          </div>
        </div>
        <button id="btn-reset" class="btn-reset">
          🔄 重新演示
        </button>
      </div>
    </div>

  </div>

  <script>
    // 教学数据配置
    const taxData = {
      school: {
        title: "🎒 公立学校与义务教育",
        desc: "我们明亮的教室、宽敞的操场、先进的多媒体设备，以及大家享受的<b>免学费义务教育</b>，背后都有国家财政的巨大投入。税收，让每个孩子都能享有平等的受教育机会！",
        color: "#3182ce"
      },
      hospital: {
        title: "🏥 公共医疗与健康保障",
        desc: "公立医院的建设、先进医疗设备的购置、传染病防控体系，以及我们生病时能报销的<b>医疗保险</b>，都离不开税收的支持。税收，是全民健康的坚实护盾！",
        color: "#319795"
      },
      road: {
        title: "🛣️ 交通设施与公共出行",
        desc: "平坦宽阔的马路、飞驰的高铁、雄伟的跨海大桥，还有路边的红绿灯和路灯。这些耗资巨大的<b>公共基础设施</b>都是由国家用税收修建的，极大地方便了我们的出行！",
        color: "#dd6b20"
      }
    };

    // 状态管理
    const exploredNodes = {
      school: false,
      hospital: false,
      road: false
    };

    // 获取 DOM 元素
    const nodes = {
      school: document.getElementById('node-school'),
      hospital: document.getElementById('node-hospital'),
      road: document.getElementById('node-road')
    };

    const lines = {
      school: document.getElementById('line-school'),
      hospital: document.getElementById('line-hospital'),
      road: document.getElementById('line-road')
    };

    const dots = {
      school: document.getElementById('dot-school'),
      hospital: document.getElementById('dot-hospital'),
      road: document.getElementById('dot-road')
    };

    const infoCard = document.getElementById('info-card');
    const cardDefault = document.getElementById('card-default');
    const cardContent = document.getElementById('card-content');
    const activeTitle = document.getElementById('active-title');
    const activeDesc = document.getElementById('active-desc');
    const progressLabel = document.getElementById('progress-label');
    const btnReset = document.getElementById('btn-reset');

    // 初始化交互事件
    Object.keys(nodes).forEach(key => {
      nodes[key].addEventListener('click', () => {
        selectNode(key);
      });
    });

    btnReset.addEventListener('click', resetSimulation);

    // 选择节点逻辑
    function selectNode(key) {
      // 1. 标记已探索
      exploredNodes[key] = true;

      // 2. 更新 SVG 节点与线条状态
      Object.keys(nodes).forEach(k => {
        if (k === key) {
          nodes[k].classList.add('active');
          nodes[k].querySelector('.node-bg').setAttribute('fill', '#48bb78'); // 激活变绿
          lines[k].classList.add('active');
        } else {
          nodes[k].classList.remove('active');
          if (!exploredNodes[k]) {
            // 未探索过的恢复原色
            const originalColors = { school: '#3182ce', hospital: '#319795', road: '#dd6b20' };
            nodes[k].querySelector('.node-bg').setAttribute('fill', originalColors[k]);
          }
        }
      });

      // 3. 更新右侧面板内容
      cardDefault.classList.add('hidden');
      cardContent.classList.remove('hidden');
      infoCard.classList.add('active');
      infoCard.style.borderColor = taxData[key].color;

      activeTitle.innerHTML = taxData[key].title;
      activeTitle.style.color = taxData[key].color;
      activeDesc.innerHTML = taxData[key].desc;

      // 4. 更新进度条
      dots[key].classList.add('active');
      const exploredCount = Object.values(exploredNodes).filter(v => v).length;
      progressLabel.textContent = `探索进度：${exploredCount} / 3`;

      // 5. 检查是否全部完成
      if (exploredCount === 3) {
        triggerCompletion();
      }
    }

    // 触发最终总结状态
    function triggerCompletion() {
      setTimeout(() => {
        infoCard.style.borderColor = '#48bb78';
        activeTitle.innerHTML = "🎉 总结：取之于民，用之于民";
        activeTitle.style.color = "#2f855a";
        activeDesc.innerHTML = "太棒了！我们发现：居民和企业依法纳税，资金汇聚到<b>国家财政</b>；国家再把这些钱用于<b>学校、医院、道路</b>等公共建设，最终回馈给每一个家庭。<br><br>这就是税收的本质：<b>取之于民，用之于民</b>。我们每个人既是纳税人，也是国家福利的受益者！";
        progressLabel.textContent = "🎉 探索完成！";
      }, 800);
    }

    // 重置模拟
    function resetSimulation() {
      Object.keys(exploredNodes).forEach(key => {
        exploredNodes[key] = false;
        nodes[key].classList.remove('active');
        lines[key].classList.remove('active');
        dots[key].classList.remove('active');

        // 恢复初始颜色
        const originalColors = { school: '#3182ce', hospital: '#319795', road: '#dd6b20' };
        nodes[key].querySelector('.node-bg').setAttribute('fill', originalColors[key]);
      });

      cardDefault.classList.remove('hidden');
      cardContent.classList.add('hidden');
      infoCard.classList.remove('active');
      infoCard.style.borderColor = '#cbd5e0';
      progressLabel.textContent = "探索进度：0 / 3";
    }
