<body>

    <div class="aspect-ratio-container">
        <!-- 头部：问题引入 -->
        <div class="header">
            <h1>理解税率的数学本质</h1>
            <div class="question-box">
                <strong>思考问题：</strong>如果一家商店的营业税率是 <strong>10%</strong>，这 10% 具体告诉了我们什么信息？它和我们之前学的百分数有什么联系？
            </div>
        </div>

        <!-- 主体：交互可视化 -->
        <div class="main-layout">
            <!-- 左侧：公式与控制 -->
            <div class="panel">
                <!-- 公式卡片 -->
                <div class="card formula-card">
                    <div class="card-title">📝 税率的数学定义</div>
                    <div class="formula-wrapper">
                        <span class="tax-rate-term">税率 (10%)</span>
                        <span>&nbsp;=&nbsp;</span>
                        <div class="fraction">
                            <span class="numerator">应纳税额</span>
                            <span class="denominator">计税收入</span>
                        </div>
                    </div>

                    <div class="dynamic-calc">
                        <span class="text-tax" id="calc-tax">100</span> 元 
                        <span> = </span>
                        <span class="text-income" id="calc-income">1000</span> 元 
                        <span> × </span>
                        <span class="text-rate">10%</span>
                    </div>
                </div>

                <!-- 控制卡片 -->
                <div class="card control-card">
                    <div class="card-title">🎛️ 动态调节计税收入</div>
                    <div class="slider-container">
                        <div class="slider-label">
                            <span>计税收入 (总额)</span>
                            <span class="text-income"><strong id="slider-val">1000</strong> 元</span>
                        </div>
                        <input type="range" id="income-slider" class="range-slider" min="100" max="1000" step="100" value="500">
                    </div>
                    <div style="font-size: 14px; line-height: 1.6; color: var(--text-muted);">
                        💡 <strong>观察：</strong>拖动滑块改变<span class="text-income">计税收入</span>时，<span class="text-rate">税率 (10%)</span> 保持不变，而<span class="text-tax">应纳税额</span>会随之发生怎样的变化？
                    </div>
                </div>
            </div>

            <!-- 右侧：直观模型 -->
            <div class="panel">
                <div class="card visual-card">
                    <!-- 视图切换 -->
                    <div class="tab-container">
                        <button class="tab-btn active" id="tab-grid">百格图模型 (部分与整体)</button>
                        <button class="tab-btn" id="tab-bills">百元纳税模型 (每100元)</button>
                    </div>

                    <!-- 可视化内容 -->
                    <div class="visual-content">
                        <!-- 模型1：百格图 -->
                        <div class="grid-model" id="grid-view">
                            <!-- 由 JS 动态生成 100 个格子 -->
                        </div>

                        <!-- 模型2：百元纳税 -->
                        <div class="bills-model hidden" id="bills-view">
                            <!-- 由 JS 动态生成百元组 -->
                        </div>
                    </div>
                </div>
            </div>
        </div>

        <!-- 底部：图例与课堂引导 -->
        <div class="footer-info">
            <div class="legend">
                <div class="legend-item">
                    <span class="legend-color" style="background-color: var(--primary-light); border: 1px solid #93c5fd;"></span>
                    <span>计税收入 (<span id="legend-income">500</span>元)</span>
                </div>
                <div class="legend-item">
                    <span class="legend-color" style="background-color: var(--tax-color);"></span>
                    <span>应纳税额 (<span id="legend-tax">50</span>元)</span>
                </div>
            </div>
            <div>
                <span>🏫 六年级数学 · 百分数应用</span>
            </div>
        </div>
    </div>

    <script>
        // 获取 DOM 元素
        const slider = document.getElementById('income-slider');
        const sliderVal = document.getElementById('slider-val');
        const calcIncome = document.getElementById('calc-income');
        const calcTax = document.getElementById('calc-tax');
        const legendIncome = document.getElementById('legend-income');
        const legendTax = document.getElementById('legend-tax');

        const tabGrid = document.getElementById('tab-grid');
        const tabBills = document.getElementById('tab-bills');
        const gridView = document.getElementById('grid-view');
        const billsView = document.getElementById('bills-view');

        const TAX_RATE = 0.10; // 10% 税率

        // 初始化百格图
        function initGrid() {
            gridView.innerHTML = '';
            for (let i = 0; i < 100; i++) {
                const cell = document.createElement('div');
                cell.classList.add('grid-cell');
                // 前10%（10个格子）代表税收
                if (i < 10) {
                    cell.classList.add('tax');
                } else {
                    cell.classList.add('income');
                }
                gridView.appendChild(cell);
            }
        }

        // 更新百元纳税模型
        function updateBillsView(income) {
            billsView.innerHTML = '';
            const hundredsCount = income / 100;

            for (let i = 0; i < hundredsCount; i++) {
                const group = document.createElement('div');
                group.classList.add('bill-group');

                const incomeBill = document.createElement('div');
                incomeBill.classList.add('bill-income');
                incomeBill.innerText = '收入 100元';

                const taxBill = document.createElement('div');
                taxBill.classList.add('bill-tax');
                taxBill.innerText = '税 10元';

                group.appendChild(incomeBill);
                group.appendChild(taxBill);
                billsView.appendChild(group);
            }
        }

        // 核心更新函数
        function update(income) {
            const tax = income * TAX_RATE;

            // 更新文本显示
            sliderVal.innerText = income;
            calcIncome.innerText = income;
            calcTax.innerText = tax;
            legendIncome.innerText = income;
            legendTax.innerText = tax;

            // 更新百元纳税模型
            updateBillsView(income);
        }

        // 事件监听：滑块拖动
        slider.addEventListener('input', (e) => {
            const income = parseInt(e.target.value);
            update(income);
        });

        // 事件监听：选项卡切换
        tabGrid.addEventListener('click', () => {
            tabGrid.classList.add('active');
            tabBills.classList.remove('active');
            gridView.classList.remove('hidden');
            billsView.classList.add('hidden');
        });

        tabBills.addEventListener('click', () => {
            tabBills.classList.add('active');
            tabGrid.classList.remove('active');
            billsView.classList.remove('hidden');
            gridView.classList.add('hidden');
        });

        // 初始化执行
        initGrid();
        update(parseInt(slider.value));
    </script>
</body>
