    const formulaBase = document.getElementById('formula-base');
    const presetButtons = document.querySelectorAll('.btn-preset');
    const thinkingText = document.getElementById('thinking-text');

    const TOTAL_INCOME = 8000;
    const BAR_LEFT = 50;
    const BAR_WIDTH = 600;
    const BAR_RIGHT = BAR_LEFT + BAR_WIDTH;

    // 更新可视化视图
    function updateVisualization(exemptValue) {
      const taxableValue = TOTAL_INCOME - exemptValue;

      // 计算比例宽度
      const exemptWidth = (exemptValue / TOTAL_INCOME) * BAR_WIDTH;
      const taxableWidth = BAR_WIDTH - exemptWidth;
      const cutX = BAR_LEFT + exemptWidth;

      // 1. 更新矩形宽度和位置
      rectExempt.setAttribute('width', exemptWidth);
      rectTaxable.setAttribute('x', cutX);
      rectTaxable.setAttribute('width', taxableWidth);

      // 2. 更新切割线位置
      cutterLine.setAttribute('x1', cutX);
      cutterLine.setAttribute('x2', cutX);
      cutterNode.setAttribute('cx', cutX);

      // 3. 动态生成下方大括号的 Path
      // 免税括号
      if (exemptWidth > 30) {
        bracketExempt.style.display = 'block';
        textExempt.style.display = 'block';
        const midExempt = BAR_LEFT + exemptWidth / 2;
        bracketExempt.setAttribute('d', `M ${BAR_LEFT},150 L ${BAR_LEFT},165 L ${midExempt - 5},165 L ${midExempt},175 L ${midExempt + 5},165 L ${cutX},165 L ${cutX},150`);
        textExempt.setAttribute('x', midExempt);
