        textTaxable.style.display = 'block';
        const midTaxable = cutX + taxableWidth / 2;
        bracketTaxable.setAttribute('d', `M ${cutX},150 L ${cutX},165 L ${midTaxable - 5},165 L ${midTaxable},175 L ${midTaxable + 5},165 L ${BAR_RIGHT},165 L ${BAR_RIGHT},150`);
        textTaxable.setAttribute('x', midTaxable);
        textTaxable.textContent = `计税基数：${taxableValue} 元`;
      } else {
        bracketTaxable.style.display = 'none';
        textTaxable.style.display = 'none';
      }

      // 4. 更新控制面板和公式文本
      sliderLabel.textContent = `免税额度：${exemptValue} 元`;
      formulaExempt.textContent = `免税额度 (${exemptValue} 元)`;
      formulaBase.textContent = `计税基数 (${taxableValue} 元)`;

      // 5. 启发式课堂提问引导
      if (exemptValue === 0) {
        thinkingText.innerHTML = "<strong>特殊情况：</strong>当免税额度为 0 时，计税基数等于什么？这意味着什么？";
      } else if (exemptValue === TOTAL_INCOME) {
        thinkingText.innerHTML = "<strong>特殊情况：</strong>当免税额度等于或超过总收入时，计税基数是多少？此时还需要纳税吗？";
