    <script>
        document.addEventListener('DOMContentLoaded', () => {
            // DOM 元素获取
            const incomeInput = document.getElementById('income-input');
            const presetBtns = document.querySelectorAll('.preset-btn');
            const rateBtns = document.querySelectorAll('.rate-btn');
            const startBtn = document.getElementById('start-btn');
            const resetBtn = document.getElementById('reset-btn');

            const guideView = document.getElementById('guide-view');
            const stepsView = document.getElementById('steps-view');
            const navView = document.getElementById('nav-view');

            const prevBtn = document.getElementById('prev-btn');
            const nextBtn = document.getElementById('next-btn');
            const stepIndicator = document.getElementById('step-indicator');

            // 步骤卡片与箭头
            const steps = [
                { card: document.getElementById('step-1'), arrow: null },
                { card: document.getElementById('step-2'), arrow: document.getElementById('arrow-1') },
                { card: document.getElementById('step-3'), arrow: document.getElementById('arrow-2') },
                { card: document.getElementById('step-4'), arrow: document.getElementById('arrow-3') }
            ];

            // 动态数据展示元素
            const step2Income = document.getElementById('step2-income');
            const step2Rate = document.getElementById('step2-rate');
            const step3Income = document.getElementById('step3-income');
            const step3RateDec = document.getElementById('step3-rate-dec');
            const step4Result = document.getElementById('step4-result');

            // 当前状态变量
            let currentStep = 0; // 0 表示未开始，1-4 表示对应步骤
            let selectedRate = 3; // 默认 3%

            // 1. 税率选择交互
            rateBtns.forEach(btn => {
                btn.addEventListener('click', () => {
                    rateBtns.forEach(b => b.classList.remove('active'));
                    btn.classList.add('active');
                    selectedRate = parseInt(btn.getAttribute('data-rate'), 10);
                    resetToInitial(); // 修改输入后重置演示状态
                });
            });

            // 2. 预设金额按钮交互
            presetBtns.forEach(btn => {
                btn.addEventListener('click', () => {
                    incomeInput.value = btn.getAttribute('data-val');
                    resetToInitial(); // 修改输入后重置演示状态
                });
            });

            // 输入框变动时重置演示
            incomeInput.addEventListener('input', () => {
                resetToInitial();
            });

            // 3. 开始演示
            startBtn.addEventListener('click', () => {
                const income = parseFloat(incomeInput.value);
                if (isNaN(income) || income <= 0) {
                    alert('请输入有效的计税收入！');
                    return;
                }

                // 计算并更新各步骤的数值
                updateFormulaValues(income, selectedRate);

                // 切换视图
                guideView.classList.add('hidden');
                stepsView.classList.remove('hidden');
                navView.classList.remove('hidden');

                // 激活第一步
                goToStep(1);
            });

            // 4. 重置按钮
            resetBtn.addEventListener('click', () => {
                resetToInitial();
            });

            // 5. 步骤导航控制
            prevBtn.addEventListener('click', () => {
                if (currentStep > 1) {
                    goToStep(currentStep - 1);
                }
            });

            nextBtn.addEventListener('click', () => {
                if (currentStep < 4) {
                    goToStep(currentStep + 1);
                }
            });

            // 更新公式中的数值
            function updateFormulaValues(income, ratePercent) {
                const rateDecimal = ratePercent / 100;
                const result = income * rateDecimal;

                // 格式化输出，保留必要的小数位
                const formattedIncome = formatNumber(income);
                const formattedResult = formatNumber(result);

                // 填充到 DOM
                step2Income.textContent = formattedIncome;
                step2Rate.textContent = ratePercent + '%';

                step3Income.textContent = formattedIncome;
                step3RateDec.textContent = rateDecimal.toString();

                step4Result.textContent = formattedResult;
            }

            // 格式化数字，防止出现超长小数
            function formatNumber(num) {
                if (Number.isInteger(num)) {
                    return num.toLocaleString('zh-CN');
                }
                return parseFloat(num.toFixed(2)).toLocaleString('zh-CN');
            }

            // 跳转到指定步骤
            function goToStep(stepNum) {
                currentStep = stepNum;

                // 更新步骤卡片状态
                steps.forEach((step, index) => {
                    const idx = index + 1;
                    if (idx < stepNum) {
                        // 已完成的步骤
                        step.card.className = 'step-card completed';
                        if (step.arrow) step.arrow.className = 'step-arrow active';
                    } else if (idx === stepNum) {
                        // 当前活跃步骤
                        step.card.className = 'step-card active';
                        if (step.arrow) step.arrow.className = 'step-arrow active';
                        // 滚动到当前活跃卡片
                        step.card.scrollIntoView({ behavior: 'smooth', block: 'nearest' });
                    } else {
                        // 未到达的步骤
                        step.card.className = 'step-card';
                        if (step.arrow) step.arrow.className = 'step-arrow';
                    }
                });

                // 更新导航按钮状态
                prevBtn.disabled = (currentStep === 1);
                nextBtn.disabled = (currentStep === 4);

                if (currentStep === 4) {
                    nextBtn.textContent = '演示完毕';
                    nextBtn.style.backgroundColor = 'var(--success-color)';
                    nextBtn.style.color = 'white';
                } else {
                    nextBtn.textContent = '下一步';
                    nextBtn.style.backgroundColor = '';
                    nextBtn.style.color = '';
                }

                stepIndicator.textContent = `步骤: ${currentStep} / 4`;
            }

            // 重置为初始未演示状态
            function resetToInitial() {
                currentStep = 0;
                guideView.classList.remove('hidden');
                stepsView.classList.add('hidden');
                navView.classList.add('hidden');

                // 重置所有卡片样式
                steps.forEach(step => {
                    step.card.className = 'step-card';
                    if (step.arrow) step.arrow.className = 'step-arrow';
                });
            }
        });
    </script>
