  <script>
    // 获取DOM元素
    const incomeSlider = document.getElementById('income-slider');
    const incomeDisplay = document.getElementById('income-display');
    const fairnessSlider = document.getElementById('fairness-slider');
    const fairnessDesc = document.getElementById('fairness-desc');

    const presetLow = document.getElementById('preset-low');
    const presetMid = document.getElementById('preset-mid');
    const presetHigh = document.getElementById('preset-high');

    const cardA = document.getElementById('card-a');
    const cardB = document.getElementById('card-b');

    const barANet = document.getElementById('bar-a-net');
    const barATax = document.getElementById('bar-a-tax');
    const barATotalLabel = document.getElementById('bar-a-total-label');
    const formulaA = document.getElementById('formula-a');
    const rateA = document.getElementById('rate-a');

    const barBNet = document.getElementById('bar-b-net');
    const barBTax = document.getElementById('bar-b-tax');
    const barBTotalLabel = document.getElementById('bar-b-total-label');
    const formulaB = document.getElementById('formula-b');
    const rateB = document.getElementById('rate-b');

    const box1 = document.getElementById('box-1');
    const box2 = document.getElementById('box-2');
    const box3 = document.getElementById('box-3');
    const box1Calc = document.getElementById('box-1-calc');
    const box2Calc = document.getElementById('box-2-calc');
    const box3Calc = document.getElementById('box-3-calc');

    // 计算税收核心逻辑
    function calculateTax() {
      const income = parseInt(incomeSlider.value);
      incomeDisplay.textContent = income.toLocaleString();

      // 方案 A 计算 (固定 10%)
      const taxA = income * 0.1;
      const netA = income - taxA;
      const pctATax = 10;
      const pctANet = 90;

      // 更新方案 A 视图
      barANet.style.width = `${pctANet}%`;
      barATax.style.width = `${pctATax}%`;
      barANet.textContent = `实收 ¥${Math.round(netA).toLocaleString()}`;
      barATax.textContent = `税额 ¥${Math.round(taxA).toLocaleString()}`;
      barATotalLabel.textContent = `${income.toLocaleString()} 元`;
      formulaA.innerHTML = `${income.toLocaleString()} &times; 10% = <strong>${Math.round(taxA).toLocaleString()} 元</strong>`;
      rateA.textContent = '10.0%';

      // 方案 B 计算 (分段)
      // 第一段: 0 - 5000 (0%)
      const limit1 = 5000;
      const fill1 = Math.min(income, limit1);
      const tax1 = 0;

      // 第二段: 5000 - 15000 (5%)
      const limit2 = 10000; // 这一段的最大跨度是 10000
      const fill2 = Math.max(0, Math.min(income - limit1, limit2));
      const tax2 = fill2 * 0.05;

      // 第三段: 15000 以上 (20%)
      const fill3 = Math.max(0, income - 15000);
      const tax3 = fill3 * 0.2;

      const taxB = tax1 + tax2 + tax3;
      const netB = income - taxB;
      const pctBTax = (taxB / income) * 100;
      const pctBNet = 100 - pctBTax;

      // 更新方案 B 视图
      barBNet.style.width = `${pctBNet}%`;
      barBTax.style.width = `${pctBTax}%`;
      barBNet.textContent = `实收 ¥${Math.round(netB).toLocaleString()}`;
      barBTax.textContent = taxB > 0 ? `税额 ¥${Math.round(taxB).toLocaleString()}` : '免税';
      barBTotalLabel.textContent = `${income.toLocaleString()} 元`;

      // 方案 B 公式展示
      let formulaBText = '';
      if (income <= 5000) {
        formulaBText = `未超起征点 5,000，免税 = <strong>0 元</strong>`;
      } else if (income <= 15000) {
        formulaBText = `(${income.toLocaleString()} - 5,000) &times; 5% = <strong>${Math.round(taxB).toLocaleString()} 元</strong>`;
      } else {
        formulaBText = `(10,000 &times; 5%) + (${(income - 15000).toLocaleString()} &times; 20%) = 500 + ${Math.round(tax3).toLocaleString()} = <strong>${Math.round(taxB).toLocaleString()} 元</strong>`;
      }
      formulaB.innerHTML = formulaBText;
      rateB.textContent = `${pctBTax.toFixed(1)}%`;

      // 更新分段计税可视化盒子
      updateBracketBox(box1, fill1, limit1, tax1, '0%', box1Calc);
      updateBracketBox(box2, fill2, limit2, tax2, '5%', box2Calc);
      updateBracketBox(box3, fill3, 25000, tax3, '20%', box3Calc); // 25000仅作为视觉上限参考

      // 高亮税负更轻的方案
      if (taxA < taxB) {
        cardA.classList.add('lighter');
        cardB.classList.remove('lighter');
      } else if (taxB < taxA) {
        cardB.classList.add('lighter');
        cardA.classList.remove('lighter');
      } else {
        cardA.classList.remove('lighter');
        cardB.classList.remove('lighter');
      }
    }

    function updateBracketBox(boxElement, fillVal, maxVal, taxVal, rateStr, calcElement) {
      if (fillVal > 0) {
        boxElement.classList.add('active');
        const fillPct = Math.min((fillVal / maxVal) * 100, 100);
        boxElement.style.setProperty('--fill-height', `${fillPct}%`);
        if (taxVal > 0) {
          calcElement.innerHTML = `额度: ¥${Math.round(fillVal).toLocaleString()}<br><span class="text-red">税: ¥${Math.round(taxVal).toLocaleString()}</span>`;
        } else {
          calcElement.innerHTML = `额度: ¥${Math.round(fillVal).toLocaleString()}<br><span class="text-green">免税</span>`;
        }
      } else {
        boxElement.classList.remove('active');
        boxElement.style.setProperty('--fill-height', `0%`);
        calcElement.innerHTML = '未启用';
      }
    }

    // 更新公平性天平解释文本
    function updateFairnessDesc() {
      const val = parseInt(fairnessSlider.value);
      let html = '';

      if (val < 35) {
        html = `
          <h4 style="color: #1e40af; margin-bottom: 6px;">⚖️ 侧重“绝对平等” (单一税率)</h4>
          <p><strong>核心观点：</strong>每个人无论收入高低，都按相同的比例（10%）纳税。规则面前人人平等，多劳多得，不惩罚高收入者的积极性。</p>
          <p style="margin-top: 6px; color: #b91c1c; font-weight: bold;">⚠️ 思考：对于低收入家庭，10%的税收可能会影响基本生活（如买食物）；而对高收入者则毫无影响。这真的公平吗？</p>
        `;
      } else if (val > 65) {
        html = `
          <h4 style="color: #9a3412; margin-bottom: 6px;">⚖️ 侧重“能力原则” (分段税率)</h4>
          <p><strong>核心观点：</strong>高收入者占有更多社会资源，有更强的支付能力，理应承担更高的税率（20%）；而对低收入者应免税保护，这体现了社会关怀与结果公平。</p>
          <p style="margin-top: 6px; color: #b91c1c; font-weight: bold;">⚠️ 思考：高收入者的财富也是通过辛勤劳动获得的，征收过高的税率是否会打击人们努力工作和创业的积极性？</p>
        `;
      } else {
        html = `
          <h4 style="color: #475569; margin-bottom: 6px;">⚖️ 兼顾“公平与效率”</h4>
          <p><strong>核心观点：</strong>现代税收通常在两者之间寻找平衡。通过设置<strong>免征额</strong>（起征点）保障低收入者的基本生存，同时实行<strong>累进税率</strong>，让高收入者多做贡献。</p>
          <p style="margin-top: 6px; color: #2563eb; font-style: italic;">💡 提示：请拖动上方“月收入”滑块，观察在什么收入水平下，两种方案的税负会发生逆转？</p>
        `;
      }
      fairnessDesc.innerHTML = html;
    }

    // 预设按钮事件
    function setPreset(income, activeBtn) {
      incomeSlider.value = income;
      [presetLow, presetMid, presetHigh].forEach(btn => btn.classList.remove('active'));
      activeBtn.classList.add('active');
      calculateTax();
    }

    // 绑定事件监听器
    incomeSlider.addEventListener('input', () => {
      // 清除预设按钮的激活状态（如果滑块值不等于预设值）
      const val = parseInt(incomeSlider.value);
      [presetLow, presetMid, presetHigh].forEach(btn => btn.classList.remove('active'));
      if (val === 4000) presetLow.classList.add('active');
      if (val === 12000) presetMid.classList.add('active');
      if (val === 30000) presetHigh.classList.add('active');
      calculateTax();
    });

    fairnessSlider.addEventListener('input', updateFairnessDesc);

    presetLow.addEventListener('click', () => setPreset(4000, presetLow));
    presetMid.addEventListener('click', () => setPreset(12000, presetMid));
    presetHigh.addEventListener('click', () => setPreset(30000, presetHigh));

    // 初始化运行
    calculateTax();
    updateFairnessDesc();
  </script>
</body>
