        const svgTaxText = document.getElementById('svg-tax-text');

        const btn5 = document.getElementById('btn-rate-5');
        const btn10 = document.getElementById('btn-rate-10');
        const btn20 = document.getElementById('btn-rate-20');

        // 更新视图主函数
        function updateVisualization() {
            const income = parseInt(incomeSlider.value);
            const rate = parseInt(rateSlider.value);
            const tax = Math.round(income * (rate / 100));

            // 1. 更新文本显示
            incomeDisplay.textContent = `${income} 元`;
            rateDisplay.textContent = `${rate}%`;

            // 2. 更新公式计算区
            calcIncome.textContent = income;
            calcRate.textContent = `${rate}%`;
            calcTax.textContent = tax;

            // 3. 更新SVG图形
            svgIncomeText.textContent = `${income} 元`;

            // 计算条形图宽度 (满宽 360px 对应 100%)
            const maxBarWidth = 360;
            const activeWidth = (rate / 100) * maxBarWidth;
