            const textX = Math.max(20, Math.min(240, activeWidth - 40));
            svgTaxText.setAttribute('transform', `translate(${textX}, 0)`);

            // 更新快捷按钮的高亮状态
            [btn5, btn10, btn20].forEach(btn => btn.classList.remove('active'));
            if (rate === 5) btn5.classList.add('active');
            if (rate === 10) btn10.classList.add('active');
            if (rate === 20) btn20.classList.add('active');
