            // 更新右侧面板数据
            const bagsCount = currentIncome / 100;
            rightBags.innerText = `${bagsCount} 个 (共 ${currentIncome} 元)`;
            rightTax.innerText = `${taxAmount.toFixed(0)} 元`;

            // 动态生成百格图
            renderGrids(bagsCount);
        }

        // 渲染百格图
        function renderGrids(count) {
            gridContainer.innerHTML = '';
            for (let i = 1; i <= count; i++) {
