                rectCost.setAttribute('stroke', '#f59e0b');
                rectCost.setAttribute('stroke-width', '2');
                rectCost.setAttribute('stroke-dasharray', '4,4');
                textTitleCost.setAttribute('fill', '#475569');
                textValCost.setAttribute('fill', '#94a3b8');
                btnCost.classList.add('deducted');
                btnCost.innerHTML = '<span>➕ 恢复 经营成本 (3万)</span>';
                formulaCost.className = 'formula-item deducted';
