            // 2. 更新上方括号（计税基数范围）
            const endX = currentX;
            bracketPath.setAttribute('d', `M 50,35 L 50,20 L ${endX},20 L ${endX},35`);

            // 计算当前计税基数值
            let baseValue = 10;
            if (isTaxFreeDeducted) baseValue -= 2;
