<script>
    // 获取DOM元素
    const btnNoDeduction = document.getElementById('btn-no-deduction');
    const btnHasDeduction = document.getElementById('btn-has-deduction');
    const sliderBox = document.getElementById('slider-box');
    const slider = document.getElementById('deduction-slider');
    const deductionValueText = document.getElementById('deduction-value');

    const rectDeduction = document.getElementById('rect-deduction');
    const rectBase = document.getElementById('rect-base');
    const textDeduction = document.getElementById('text-deduction');
    const textBase = document.getElementById('text-base');
    const relationSymbol = document.getElementById('relation-symbol');
    const linkLineRight = document.getElementById('link-line-right');

    const formulaDeduction = document.getElementById('formula-deduction');
    const formulaBase = document.getElementById('formula-base');

    // 常量定义
    const TOTAL_INCOME = 10000;
    const SVG_MAX_WIDTH = 300; // 对应10000元在SVG中的像素宽度
    const SVG_START_X = 50;

    // 状态变量
    let currentDeduction = 0;
    let hasDeductionPolicy = false;

    // 更新视图函数
    function updateVisualization() {
        const deduction = hasDeductionPolicy ? currentDeduction : 0;
        const taxBase = TOTAL_INCOME - deduction;

        // 计算对应的像素宽度
        const deductionWidth = (deduction / TOTAL_INCOME) * SVG_MAX_WIDTH;
        const baseWidth = (taxBase / TOTAL_INCOME) * SVG_MAX_WIDTH;

        // 1. 更新免税额矩形和文本
        rectDeduction.setAttribute('width', deductionWidth);
        if (deduction > 0) {
            rectDeduction.setAttribute('fill-opacity', '0.85');
            textDeduction.setAttribute('opacity', '1');
            textDeduction.setAttribute('x', SVG_START_X + deductionWidth / 2);
            textDeduction.textContent = `${deduction}`;
        } else {
            textDeduction.setAttribute('opacity', '0');
        }

        // 2. 更新计税基数矩形和文本
        rectBase.setAttribute('x', SVG_START_X + deductionWidth);
        rectBase.setAttribute('width', baseWidth);
        textBase.setAttribute('x', SVG_START_X + deductionWidth + baseWidth / 2);
        textBase.textContent = `${taxBase} 元`;

        // 3. 更新关系符号和辅助线
        if (deduction === 0) {
            relationSymbol.textContent = '=';
            relationSymbol.setAttribute('fill', '#10b981'); // 绿色表示完全相等
            linkLineRight.setAttribute('d', `M 350 90 L 350 130`); // 右侧对齐
        } else {
            relationSymbol.textContent = '≠';
            relationSymbol.setAttribute('fill', '#ef4444'); // 红色表示不等
            // 右侧虚线指向计税基数的起始分割点，直观展示“被截去一部分”
            const splitX = SVG_START_X + deductionWidth;
            linkLineRight.setAttribute('d', `M 350 90 L ${splitX} 130`);
        }

        // 4. 更新底部公式和控制面板文本
        deductionValueText.textContent = `${deduction} 元`;
        formulaDeduction.textContent = `免税额 (${deduction})`;
        formulaBase.textContent = `计税基数 (${taxBase})`;
    }

    // 事件监听：无免税方案
    btnNoDeduction.addEventListener('click', () => {
        if (!btnNoDeduction.classList.contains('active')) {
            btnNoDeduction.classList.add('active');
            btnHasDeduction.classList.remove('active');
            sliderBox.classList.add('disabled');
            slider.disabled = true;
            hasDeductionPolicy = false;
            updateVisualization();
        }
    });

    // 事件监听：有免税方案
    btnHasDeduction.addEventListener('click', () => {
        if (!btnHasDeduction.classList.contains('active')) {
            btnHasDeduction.classList.add('active');
            btnNoDeduction.classList.remove('active');
            sliderBox.classList.remove('disabled');
            slider.disabled = false;
            hasDeductionPolicy = true;
            // 默认给一个起征点值，比如 3000
            if (slider.value == 0) {
                slider.value = 3000;
            }
            currentDeduction = parseInt(slider.value);
            updateVisualization();
        }
    });

    // 事件监听：滑动条变化
    slider.addEventListener('input', (e) => {
        currentDeduction = parseInt(e.target.value);
        updateVisualization();
    });

    // 初始化
    updateVisualization();
</script>

