    const tabPersonal = document.getElementById('tab-personal');
    const formulaTaxLabel = document.getElementById('formula-tax-label');
    const formulaBaseLabel = document.getElementById('formula-base-label');
    const sliderBaseTitle = document.getElementById('slider-base-title');
    const sliderBase = document.getElementById('slider-base');
    const sliderRate = document.getElementById('slider-rate');
    const valBase = document.getElementById('val-base');
    const valRate = document.getElementById('val-rate');
    const calcSentence = document.getElementById('calc-sentence');
    const svgTaxBar = document.getElementById('svg-tax-bar');
    const svgBaseText = document.getElementById('svg-base-text');
    const svgTaxText = document.getElementById('svg-tax-text');
    const svgRateText = document.getElementById('svg-rate-text');

    // 初始化
    function init() {
      setupEventListeners();
      updateUI();
    }

    // 事件监听
    function setupEventListeners() {
      tabBusiness.addEventListener('click', () => switchTab('business'));
      tabPersonal.addEventListener('click', () => switchTab('personal'));

      sliderBase.addEventListener('input', (e) => {
        state[state.currentTab].base = parseFloat(e.target.value);
        updateUI();
      });

      sliderRate.addEventListener('input', (e) => {
        state[state.currentTab].rate = parseFloat(e.target.value);
        updateUI();
      });
    }

    // 切换选项卡
    function switchTab(tab) {
      if (state.currentTab === tab) return;
      state.currentTab = tab;

      if (tab === 'business') {
        tabBusiness.classList.add('active');
        tabPersonal.classList.remove('active');
      } else {
        tabPersonal.classList.add('active');
        tabBusiness.classList.remove('active');
      }

      // 重置滑块属性
      const config = state[tab];
      sliderBase.min = config.baseMin;
      sliderBase.max = config.baseMax;
      sliderBase.step = config.baseStep;
      sliderBase.value = config.base;

      sliderRate.min = config.rateMin;
      sliderRate.max = config.rateMax;
      sliderRate.step = config.rateStep;
      sliderRate.value = config.rate;

      updateUI();

      // 添加切换动画效果
      const formulaCard = document.querySelector('.model-card');
      formulaCard.classList.remove('fade-enter');
      void formulaCard.offsetWidth; // 触发重绘
      formulaCard.classList.add('fade-enter');
    }

    // 更新界面渲染
    function updateUI() {
      const current = state[state.currentTab];
      const baseVal = current.base;
      const rateVal = current.rate;
      const taxVal = Math.round(baseVal * (rateVal / 100) * 100) / 100;

      // 1. 更新公式标签
      formulaBaseLabel.textContent = current.baseLabel;
      formulaTaxLabel.textContent = current.taxLabel;

      // 2. 更新控制面板文字
      sliderBaseTitle.textContent = `${current.baseLabel} (基数)`;
      valBase.textContent = `${baseVal.toLocaleString()} 元`;
      valRate.textContent = `${rateVal}%`;

      // 3. 更新计算公式
      calcSentence.innerHTML = `计算过程：<span style="color:#2b6cb0">${baseVal.toLocaleString()}</span> × <span style="color:#319795">${rateVal}%</span> = <span style="color:#dd6b20; font-size: 18px;">${taxVal.toLocaleString()} 元</span>`;

      // 4. 更新 SVG 可视化条
      const maxSvgWidth = 680;
      const taxBarWidth = maxSvgWidth * (rateVal / 100);
      svgTaxBar.setAttribute('width', taxBarWidth);

      // 动态调整文字位置
      svgBaseText.textContent = `${current.baseLabel}: ${baseVal.toLocaleString()} 元 (100%)`;

      if (rateVal > 8) {
        svgTaxText.textContent = `${taxVal.toLocaleString()}元`;
        svgTaxText.setAttribute('x', taxBarWidth / 2 + 10);
