    // (20000 - 5000) * 0.133333 = 2000
    function calcTax1(income) {
        if (income <= 5000) return 0;
        return Math.round((income - 5000) * 0.133333);
    }

    // 方案二公式：起征点8000，税率8.3333% (为了在20000元时刚好是1000元)
