        // 1个金币代表100元税额
        const coinCount = Math.min(30, Math.round(tax / 100)); 
        const coinsPerRow = 4;

        for (let i = 0; i < coinCount; i++) {
            const row = Math.floor(i / coinsPerRow);
            const col = i % coinsPerRow;

            // 计算金币在托盘上的相对位置
            const x = -22 + col * 12;
            const y = 84 - row * 5;

            const rect = document.createElementNS("http://www.w3.org/2000/svg", "rect");
            rect.setAttribute("x", x);
            rect.setAttribute("y", y);
            rect.setAttribute("width", 10);
            rect.setAttribute("height", 4);
            rect.setAttribute("rx", 1);

            if (isScheme1) {
                rect.setAttribute("fill", "#f1c40f");
                rect.setAttribute("stroke", "#d35400");
            } else {
                rect.setAttribute("fill", "#a3e635");
                rect.setAttribute("stroke", "#15803d");
            }
            rect.setAttribute("stroke-width", "0.5");
