        sliderVal.innerText = income.toLocaleString() + ' 元';
        tax1Display.innerText = tax1.toLocaleString() + ' 元';
        tax2Display.innerText = tax2.toLocaleString() + ' 元';
        diffDisplay.innerText = diff.toLocaleString() + ' 元';
        svgDiffText.innerText = '差额: ' + diff.toLocaleString() + '元';
        equityValText.innerText = diff.toLocaleString() + '元';

        // 计算天平倾斜角度 (差额越大，倾斜越明显，最大限制在20度)
        // 方案一税重大，向左倾斜（SVG中逆时针为负角度）
        let angle = 0;
        if (diff > 0) {
            angle = -Math.min(20, diff * 0.012);
