  <script>
    const gridContainer = document.getElementById('grid-container');
    const slider = document.getElementById('grid-slider');
    const sliderVal = document.getElementById('slider-val');
    const formulaNum = document.getElementById('formula-num');
    const formulaPercent = document.getElementById('formula-percent');
    const infoText = document.getElementById('info-text');

    const btnTax = document.getElementById('btn-tax');
    const btnReset = document.getElementById('btn-reset');
    const btnRandom = document.getElementById('btn-random');

    let currentCount = 10; // 默认10%

    // 初始化生成100个格子
    function createGrid() {
      gridContainer.innerHTML = '';
      for (let i = 0; i < 100; i++) {
        const cell = document.createElement('div');
        cell.classList.add('cell');
        cell.dataset.index = i;

        // 点击格子直接设置填充数量
        cell.addEventListener('click', () => {
          updateState(i + 1);
        });

        // 鼠标悬停预览效果
        cell.addEventListener('mouseenter', () => {
          previewState(i + 1);
        });

        gridContainer.appendChild(cell);
      }

      // 鼠标移出网格恢复当前实际状态
      gridContainer.addEventListener('mouseleave', () => {
        renderGrid(currentCount);
      });
    }

    // 更新全局状态
    function updateState(count) {
      currentCount = count;
      slider.value = count;
      sliderVal.textContent = count;
      renderGrid(count);
      updateFormula(count);
    }

    // 仅渲染网格视觉（用于悬停预览）
    function renderGrid(count) {
      const cells = gridContainer.querySelectorAll('.cell');
      cells.forEach((cell, idx) => {
        cell.classList.remove('preview');
        if (idx < count) {
          cell.classList.add('active');
        } else {
          cell.classList.remove('active');
        }
      });
    }

    // 悬停预览
    function previewState(count) {
      const cells = gridContainer.querySelectorAll('.cell');
      cells.forEach((cell, idx) => {
        if (idx < count) {
          if (!cell.classList.contains('active')) {
            cell.classList.add('preview');
          }
        } else {
          cell.classList.remove('active');
          cell.classList.remove('preview');
        }
      });
    }

    // 更新公式与情境文本
    function updateFormula(count) {
      formulaNum.textContent = count;
      formulaPercent.textContent = count + '%';

      // 动态更新情境描述，增强代入感
      if (count === 10) {
        infoText.innerHTML = `如果国家规定“每100元收入要交10元税”，这10元占100元的 <span class="highlight-text">10/100</span>，也就是 <span class="highlight-text">10%</span>。此时税率就是10%。`;
      } else if (count === 0) {
        infoText.innerHTML = `当填充为 0 时，表示没有交税。占总收入的 <span class="highlight-text">0/100</span>，即 <span class="highlight-text">0%</span>。`;
      } else if (count === 100) {
        infoText.innerHTML = `当填充 100 格时，表示全部收入都要交税！占总收入的 <span class="highlight-text">100/100</span>，即 <span class="highlight-text">100%</span>（整体）。`;
      } else {
        infoText.innerHTML = `如果每100元收入要交 <span class="highlight-text">${count}</span> 元税，这部分税收就占总收入的 <span class="highlight-text">${count}/100</span>，也就是 <span class="highlight-text">${count}%</span>。`;
      }
    }

    // 滑块事件监听
    slider.addEventListener('input', (e) => {
      updateState(parseInt(e.target.value));
    });

    // 预设按钮事件
    btnTax.addEventListener('click', () => {
      updateState(10);
    });

    btnReset.addEventListener('click', () => {
      updateState(0);
    });

    btnRandom.addEventListener('click', () => {
      const randomVal = Math.floor(Math.random() * 101);
      updateState(randomVal);
    });

    // 初始化执行
    createGrid();
    updateState(10);
  </script>
</body>
