  <script>
    const slider = document.getElementById('tax-free-slider');
    const taxFreeVal = document.getElementById('tax-free-val');
    const taxFreeRect = document.getElementById('taxfree-rect');
    const taxableRect = document.getElementById('taxable-rect');
    const cutLine = document.getElementById('cut-line');
    const scissors = document.getElementById('scissors');
    const topBracket = document.getElementById('top-bracket');
    const freeBracket = document.getElementById('free-bracket');
    const taxableBracket = document.getElementById('taxable-bracket');
    const freeLabel = document.getElementById('free-label');
    const taxableLabel = document.getElementById('taxable-label');
    const bubble = document.getElementById('bubble');
    const hintBubble = document.getElementById('hint-bubble');
    const resetBtn = document.getElementById('reset-btn');

    const totalIncome = 8000;
    const startX = 100;
    const totalWidth = 600;
    const scale = totalWidth / totalIncome;

    let hasClickedCorrect = false;

    // 生成大括号的 SVG Path (朝上或朝下)
    function getBracketPath(x1, x2, y, direction) {
      const size = 10;
      const mid = (x1 + x2) / 2;
      if (direction === 'up') {
        return `M ${x1},${y} 
                L ${x1},${y - size} 
                L ${mid - size},${y - size} 
                L ${mid},${y - size - 8} 
                L ${mid + size},${y - size} 
                L ${x2},${y - size} 
                L ${x2},${y}`;
      } else {
        return `M ${x1},${y} 
                L ${x1},${y + size} 
                L ${mid - size},${y + size} 
                L ${mid},${y + size + 8} 
                L ${mid + size},${y + size} 
                L ${x2},${y + size} 
                L ${x2},${y}`;
      }
    }

    // 定位 HTML 气泡到 SVG 坐标
    function positionBubble(el, svgX, svgY) {
      const pctX = (svgX / 800) * 100;
      const pctY = (svgY / 420) * 100;
      el.style.left = `${pctX}%`;
      el.style.top = `${pctY}%`;
    }

    // 更新视图
    function update() {
      const taxFree = parseInt(slider.value);
      const taxable = totalIncome - taxFree;

      const w_free = taxFree * scale;
      const w_taxable = taxable * scale;

      // 1. 更新矩形宽度和位置
      taxFreeRect.setAttribute('width', w_free);
      taxableRect.setAttribute('x', startX + w_free);
      taxableRect.setAttribute('width', w_taxable);

      // 2. 更新剪裁线和剪刀位置
      const cutX = startX + w_free;
      cutLine.setAttribute('x1', cutX);
      cutLine.setAttribute('x2', cutX);
      scissors.setAttribute('x', cutX);

      // 3. 更新上方大括号 (总收入)
      topBracket.setAttribute('d', getBracketPath(startX, startX + totalWidth, 130, 'up'));

      // 4. 更新下方大括号与文本
      if (taxFree > 0) {
        freeBracket.setAttribute('display', 'inline');
        freeLabel.setAttribute('display', 'inline');
        freeBracket.setAttribute('d', getBracketPath(startX, cutX, 230, 'down'));

        const midFree = startX + w_free / 2;
        freeLabel.setAttribute('x', midFree);
        freeLabel.innerHTML = `<tspan x="${midFree}" dy="0">免税部分</tspan><tspan x="${midFree}" dy="20" fill="#6b7280" font-size="14">${taxFree} 元</tspan>`;
      } else {
        freeBracket.setAttribute('display', 'none');
        freeLabel.setAttribute('display', 'none');
      }

      if (taxable > 0) {
        taxableBracket.setAttribute('display', 'inline');
        taxableLabel.setAttribute('display', 'inline');
        taxableBracket.setAttribute('d', getBracketPath(cutX, startX + totalWidth, 230, 'down'));

        const midTaxable = cutX + w_taxable / 2;
        taxableLabel.setAttribute('x', midTaxable);
        taxableLabel.innerHTML = `<tspan x="${midTaxable}" dy="0">计税部分 (应纳税所得额)</tspan><tspan x="${midTaxable}" dy="20" fill="#1d4ed8" font-size="14">${taxable} 元</tspan>`;
      } else {
        taxableBracket.setAttribute('display', 'none');
        taxableLabel.setAttribute('display', 'none');
      }

      // 5. 动态更新数值显示
      taxFreeVal.textContent = `${taxFree} 元`;

      // 6. 动态更新气泡位置
      if (bubble.classList.contains('visible')) {
        positionBubble(bubble, cutX + w_taxable / 2, 130);
      }
      if (hintBubble.classList.contains('visible')) {
        positionBubble(hintBubble, startX + w_free / 2, 130);
      }
    }

    // 事件监听
    slider.addEventListener('input', () => {
      update();
      // 拖动时隐藏提示，鼓励重新点击
      bubble.classList.remove('visible');
      hintBubble.classList.remove('visible');
      taxableRect.classList.remove('highlighted');
    });

    taxableRect.addEventListener('click', () => {
      taxableRect.classList.add('highlighted');
      bubble.classList.add('visible');
      hintBubble.classList.remove('visible');
      hasClickedCorrect = true;
      update();
    });

    taxFreeRect.addEventListener('click', () => {
      if (parseInt(slider.value) > 0) {
        hintBubble.classList.add('visible');
        bubble.classList.remove('visible');
        taxableRect.classList.remove('highlighted');
        update();
      }
    });

    resetBtn.addEventListener('click', () => {
      slider.value = 3000;
      taxableRect.classList.remove('highlighted');
      bubble.classList.remove('visible');
      hintBubble.classList.remove('visible');
      hasClickedCorrect = false;
      update();
    });

    // 初始化
    update();
  </script>
