    <script>
        // 获取DOM元素
        const sliderIncome = document.getElementById('slider-income');
        const sliderAllowance = document.getElementById('slider-allowance');
        const lblIncome = document.getElementById('lbl-income');
        const lblAllowance = document.getElementById('lbl-allowance');

        const valIncome = document.getElementById('val-income');
        const valAllowance = document.getElementById('val-allowance');
        const valResult = document.getElementById('val-result');
        const resultLabel = document.getElementById('result-label');

        const cardIncome = document.getElementById('card-income');
        const cardAllowance = document.getElementById('card-allowance');
        const cardResult = document.getElementById('card-result');

        const barAllowance = document.getElementById('bar-allowance');
        const barTaxable = document.getElementById('bar-taxable');
        const textBarAllowance = document.getElementById('text-bar-allowance');
        const textBarTaxable = document.getElementById('text-bar-taxable');
        const bracketTaxable = document.getElementById('bracket-taxable');
        const bracketText = document.getElementById('bracket-text');

        const messageBox = document.getElementById('message-box');

        let isRevealed = false;

        // 更新视图函数
        function updateVisualization() {
            const income = parseInt(sliderIncome.value);
            const allowance = parseInt(sliderAllowance.value);

            // 确保总收入不低于免税额
            if (income < allowance) {
                sliderIncome.value = allowance;
                updateVisualization();
                return;
            }

            const taxable = income - allowance;

            // 更新文本显示
            lblIncome.textContent = income + '元';
            lblAllowance.textContent = allowance + '元';
            valIncome.textContent = income + ' 元';
            valAllowance.textContent = allowance + ' 元';

            // 计算SVG条形图比例 (总宽度 780px 对应最大值 15000)
            const maxVal = 15000;
            const startX = 10;
            const totalWidth = 780;

            const widthAllowance = (allowance / maxVal) * totalWidth;
            const widthTaxable = (taxable / maxVal) * totalWidth;
            const xTaxable = startX + widthAllowance;

            // 更新免税额条
            barAllowance.setAttribute('width', widthAllowance);
            textBarAllowance.setAttribute('x', startX + widthAllowance / 2);
            textBarAllowance.textContent = `免税额 (${allowance}元)`;

            // 更新计税基数条
            barTaxable.setAttribute('x', xTaxable);
            barTaxable.setAttribute('width', widthTaxable);

            // 更新大括号和标注
            const midTaxable = xTaxable + widthTaxable / 2;
            bracketTaxable.setAttribute('d', `M ${xTaxable} 65 L ${xTaxable} 75 L ${midTaxable} 75 L ${midTaxable} 80 L ${midTaxable} 75 L ${startX + widthAllowance + widthTaxable} 75 L ${startX + widthAllowance + widthTaxable} 65`);
            bracketText.setAttribute('x', midTaxable);

            if (isRevealed) {
                valResult.textContent = "计税基数";
                resultLabel.textContent = `差额: ${taxable} 元`;
                textBarTaxable.textContent = `计税基数 (${taxable}元)`;
                barTaxable.setAttribute('fill', '#10b981');
                bracketText.textContent = `计税基数 = ${taxable} 元`;
            } else {
                valResult.textContent = "？";
                resultLabel.textContent = "点击揭晓答案";
                textBarTaxable.textContent = "？";
                barTaxable.setAttribute('fill', '#f59e0b');
                bracketText.textContent = "先扣除，再计算";
            }
        }

        // 揭晓答案交互
        cardResult.addEventListener('click', () => {
            isRevealed = true;
            cardResult.classList.remove('pulse-effect');
            cardResult.classList.add('revealed');

            messageBox.className = "message-box success";
            messageBox.innerHTML = "🎉 <strong>正确！这个差额叫做【计税基数】（也称应纳税所得额）。</strong><br>记住：在计算任何税率之前，必须【先做减法】扣除免税额，确定基数！";

            updateVisualization();
        });

        // 点击数字卡片提示“先做减法”
        const promptSubAction = () => {
            messageBox.className = "message-box warning";
            messageBox.innerHTML = "💡 <strong>先做减法！</strong> 无论我们要计算多少税率，第一步永远是：用总收入减去免税额，确定【计税基数】。";
        };

        cardIncome.addEventListener('click', promptSubAction);
        cardAllowance.addEventListener('click', promptSubAction);

        // 滑块交互
        sliderIncome.addEventListener('input', () => {
            if (parseInt(sliderIncome.value) < parseInt(sliderAllowance.value)) {
                sliderAllowance.value = sliderIncome.value;
            }
            updateVisualization();
        });

        sliderAllowance.addEventListener('input', () => {
            if (parseInt(sliderAllowance.value) > parseInt(sliderIncome.value)) {
                sliderIncome.value = sliderAllowance.value;
            }
            updateVisualization();
        });

        // 初始化
        updateVisualization();
    </script>
</body>
